#!/usr/bin/env bash
# Photorealistic renders of skAItch 3D captures, generated by Codex (gpt-6.1-terra, low effort).
# Usage: apps/site/scripts/render-codex.sh   (writes apps/site/public/media/render-*.png)
set -euo pipefail
media="$(cd "$(dirname "$0")/../public/media" && pwd)"

prompt() {
  cat <<EOF
Using your image generation tool, turn the attached 3D model view of a single-storey house into a photorealistic architectural photograph, then save it as $1 in the current directory.
Keep exactly the same camera position, perspective and framing, the same footprint, wall heights, gable roof shape and pitch, and the same number, positions and proportions of windows and doors.
Materials: warm off-white lime render walls, terracotta clay roof tiles, anthracite aluminium window frames with clear glass, light stone sills, a solid oak front door.
Surroundings: mown lawn, gravel path to the front door, a few low shrubs, calm residential setting. Soft natural daylight, light clouds, realistic shadows.
No text, no grid, no dimension lines, no people. Do not modify any other file.
EOF
}

render() {
  local input="$1" output="$2"
  # -i takes several files, so the prompt goes through stdin.
  prompt "$output" | codex exec -m gpt-6.1-terra -c model_reasoning_effort=low --skip-git-repo-check \
    -s workspace-write -C "$media" -i "$media/$input"
  test -s "$media/$output" && echo "written $media/$output"
}

render view-front.jpg render-front.png
render model-3d.jpg render-aerial.png
